    selfcheck=[ex("¿Qué es transporte?", "Medio para llevar personas y cosas", "Incluye buses y camiones."), ex("¿Qué es comunicación?", "Medio para enviar información", "Incluye teléfono y radio."), ex("¿Qué son los bienes?", "Cosas que se producen y se usan", "Por ejemplo, alimentos.")],
    open_task=task("Haz una tabla de dos columnas: «Transporte» y «Comunicación». Escribe tres medios en cada una. Puedes usar: bus, tren, camión, teléfono, radio, carta, avión, televisión. Escribe una frase que compare uno de cada columna.", "Transporte: bus, tren, camión. Comunicación: teléfono, radio, carta. El bus lleva personas y el teléfono lleva mensajes.", ["clasifica seis medios", "no mezcla columnas", "escribe una comparación"], ["tabla", "frase"], ["poner la radio en transporte", "no comparar"], "Revisa con un adulto cada medio en su columna."),
