    selfcheck=[ex("¿Qué es un deterioro?", "Un daño en un lugar", "Se puede ver."), ex("En Historia: ¿Qué es una causa?", "Lo que provoca algo", "La causa viene primero."), ex("¿Describes culpando o contando lo que se ve?", "Contando lo que se ve", "Así se evita pelear.")],
    open_task=task("Elige un caso: plaza con pocos basureros, patio con la cancha rota o baño sin papel. Escribe en tres frases el problema, una causa posible y un efecto. No culpes a ningún grupo.", "Elegí la plaza con pocos basureros. El problema: hay papeles en el pasto. Causa: faltan basureros. Efecto: nadie quiere sentarse.", ["describe lo que se ve", "separa causa y efecto", "no culpa a un grupo"], ["tres frases"], ["culpar a un grupo", "confundir causa y efecto"], "Lee tu texto a un adulto y pregunta si queda claro qué pasa y por qué."),
